sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	try{
		var targetSysId = current.correlation_id;
		if(!targetSysId){
			gs.info("[Table Integration PATCH] No Correlation ID found");
			return;
		}
		gs.info("[Table Integration PATCH] Correlation ID: " + targetSysId);
		var request = new sn_ws.RESTMessageV2('Table API Instance A to B', 'PATCH Method'); 
		request.setStringParameterNoEscape('target_sys_id', targetSysId);

		var payload = {
			"opened_by": current.opened_by.toString() || '',
			"requestor": current.requestor.toString() || '',
			"type_of_asset": current.type_of_asset.toString() || '',
			"consumables": current.consumables.toString() || '',
			"company": current.company.toString() || '',
			"priority": current.priority.toString() || '',
			"short_description": current.short_description.toString() || '',
			"description": current.description.toString() || ''
		};

		request.setRequestBody(JSON.stringify(payload));

		var response = request.execute();
		var httpStatus = response.getStatusCode();
		var responseBody = response.getBody();

		if (httpStatus == 200) {
            gs.info("[Table Integration PATCH] Successfully updated record in Instance B. SysID: " + targetSysId);
        } else {
            gs.error("[Table Integration PATCH] Failed to update record in Instance B. Status: " + httpStatus + " Response: " + responseBody);
        }
	}
	catch(ex){
		gs.info("[Table Integration PATCH] Instance B update error: " + ex.getMessage());
	}

})(current, previous);
